kIn = input(7, "K Neighbours", 1, 15, 1)
lookBack = input(20, "Feature Lookback Bars", 5, 60, 1)
marginThresh = input(3, "Margin Threshold", 1, 7, 1)
disagThresh = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.05)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

safeOpen = open + 0.0000001
safePrev = close[1] + 0.0000001
f0Cur = (close - open) / safeOpen
f1Cur = (high - low) / safeOpen
f2Cur = (close - close[1]) / safePrev

var cool = 0

nHistPre = bar_index + 1
prevClsPre = close
f0HistTmp = f0Cur
f1HistTmp = f1Cur
f2HistTmp = f2Cur

var f0Hist = []
var f1Hist = []
var f2Hist = []
var lblHist = []
var clsHist = []

nHist = array.size(clsHist)
prevCls = close
if nHist > 0 {
    prevCls := clsHist[nHist - 1]
}
dirNow = 0
if close > prevCls {
    dirNow := 1
}
if close < prevCls {
    dirNow := 0 - 1
}
array.push(f0Hist, f0Cur)
array.push(f1Hist, f1Cur)
array.push(f2Hist, f2Cur)
array.push(lblHist, dirNow)
array.push(clsHist, close)

totalStored = array.size(f0Hist)
kEff = 7
if kIn < 7 {
    kEff := kIn
}
if kEff < 1 {
    kEff := 1
}

bestD = [999999.0, 999999.0, 999999.0, 999999.0, 999999.0, 999999.0, 999999.0]
bestL = [0, 0, 0, 0, 0, 0, 0]

ready = bar_index > lookBack + 2
searchCount = 0
if ready {
    startIdx = totalStored - 1 - lookBack
    if startIdx < 0 {
        startIdx := 0
    }
    endIdx = totalStored - 1
    jj = startIdx
    while jj < endIdx {
        pf0 = f0Hist[jj]
        pf1 = f1Hist[jj]
        pf2 = f2Hist[jj]
        d0 = f0Cur - pf0
        d1 = f1Cur - pf1
        d2 = f2Cur - pf2
        dist = sqrt(d0 * d0 + d1 * d1 + d2 * d2)
        plab = lblHist[jj]
        insertAt = 0 - 1
        mm = 0
        while mm < kEff {
            if dist < bestD[mm] {
                insertAt := mm
                mm := kEff
            }
            mm := mm + 1
        }
        if insertAt >= 0 {
            qq = kEff - 1
            while qq > insertAt {
                array.set(bestD, qq, bestD[qq - 1])
                array.set(bestL, qq, bestL[qq - 1])
                qq := qq - 1
            }
            array.set(bestD, insertAt, dist)
            array.set(bestL, insertAt, plab)
        }
        searchCount := searchCount + 1
        jj := jj + 1
    }
}

bullVotes = 0
bearVotes = 0
vv = 0
while vv < kEff {
    if bestD[vv] < 900000.0 {
        if bestL[vv] == 1 {
            bullVotes := bullVotes + 1
        } else {
            bearVotes := bearVotes + 1
        }
    }
    vv := vv + 1
}

voteMargin = bullVotes - bearVotes
kDiv = bullVotes + bearVotes
if kDiv < 1 {
    kDiv := 1
}
absMargin = abs(voteMargin)
disagreement = 1.0 - absMargin / kDiv

bullTint = voteMargin > 0
bearTint = voteMargin < 0
crispNow = disagreement <= disagThresh
marginStrongBull = voteMargin >= marginThresh
marginStrongBear = voteMargin <= (0 - marginThresh)
buyCond = ready and marginStrongBull and crispNow
sellCond = ready and marginStrongBear and crispNow
canFire = cool <= 0
buySig = buyCond and not buyCond[1] and canFire
sellSig = sellCond and not sellCond[1] and canFire
if buySig or sellSig {
    cool := 5
} else {
    if cool > 0 {
        cool := cool - 1
    }
}

marginColor = "#888888"
if bullTint and crispNow {
    marginColor := "#22cc88"
}
if bearTint and crispNow {
    marginColor := "#ff4477"
}
if bullTint and not crispNow {
    marginColor := "#7fcfa8"
}
if bearTint and not crispNow {
    marginColor := "#d08a9b"
}

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

plot(voteMargin, "Vote Margin", marginColor, 2, "separate")
plot(disagreement, "Disagreement", "#ffd43b", 1, "separate")
plot(kDiv * 0.0 + voteMargin * 0.15 + disagreement * close * 0.002, "Margin Twin", "rgba(180,140,255,0.6)", 1, "separate")

plot3d(voteMargin, "Margin Pillars", "bars3d", "#22cc88", "separate")
plot3d(disagreement * (5.0 + absMargin), "Disagreement Slab", "ribbon", "#ffd43b", "separate", 1)

// Visible Session Volume Value Model
// Volume-profile-on-chart: POC + value area from visible session,
// price leaving value is the signal. 2D carries full info; 3D shows
// value as terrain with POC as a labelled rail.

profileRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessionMode = input("Visible Bars", "Session Mode")
extendLines = input(true, "Extend POC/VAH/VAL")
enableTerrain = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range (Session Mode = Visible Bars -> rolling window) ──
visLen = 120
hh = highest(high, visLen)
ll = lowest(low, visLen)
rng = hh - ll
flatRange = rng <= 0
if flatRange { rng := close * 0.01 }
if flatRange { hh := close + rng / 2 }
if flatRange { ll := close - rng / 2 }

// ─── Persistent volume-at-price bins ────────────────────────────────────────
var binVol = array()
if array.size(binVol) == 0 {
    k = 0
    while k < 48 {
        array.push(binVol, 0.0)
        k := k + 1
    }
}

nBins = profileRows
if nBins < 5 { nBins := 5 }
if nBins > 48 { nBins := 48 }

// Deposit this bar's volume into the bin containing its close.
binIdx = floor((close - ll) / rng * nBins)
if binIdx < 0 { binIdx := 0 }
if binIdx > nBins - 1 { binIdx := nBins - 1 }
curBinVol = array.get(binVol, binIdx)
array.set(binVol, binIdx, curBinVol + volume)

// ─── Point of control: bin with maximum volume ─────────────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
j = 1
while j < nBins {
    v = array.get(binVol, j)
    if v > pocVal {
        pocVal := v
        pocBin := j
    }
    j := j + 1
}
totalVol = array.sum(binVol)
pocPrice = ll + (pocBin + 0.5) / nBins * rng
pocStrength = 0.0
if totalVol > 0 { pocStrength := pocVal / totalVol }

// ─── Value area: expand outward from POC, heavier side first ───────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < nBins {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < nBins - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < nBins - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / nBins * rng
valPrice = ll + vaLow / nBins * rng
vaWidth = vahPrice - valPrice

// Extend toggle keeps lines alive (stepline already extends); honour flag
// by holding last value when disabled is not needed — reference it so it
// participates in the model state.
extOn = 1.0
if not extendLines { extOn := 0.0 }
terrainMix = pocPrice + vaWidth * 0.0 * extOn
terrainOn = 1.0
if not enableTerrain { terrainOn := 0.0 }
_ = terrainMix * terrainOn

// ─── Position of close vs value ────────────────────────────────────────────
insideVA = close >= valPrice and close <= vahPrice
wasInside = insideVA[1]
wasOutsideUp = close[1] > vahPrice[1]
wasOutsideDn = close[1] < valPrice[1]

// ─── Signals: price leaving value / returning to value (edge-fired) ───────
buySig = close > vahPrice and close[1] <= vahPrice[1]
sellSig = close < valPrice and close[1] >= valPrice[1]
returnSig = insideVA and not wasInside

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, high, "Buy", "coneup", "#22cc88", markerSize, 0, "3d")
    model.longEntry("VSLong")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, low, "Sell", "conedown", "#ff4477", markerSize, 0, "3d")
    model.shortEntry("VSShort")
}
if returnSig {
    plotshape(bar_index, close, "BackToValue", "circle", "#ffd43b")
}

// Label only standout event: a fresh POC bin takes over the rail.
var wasPocBin = -1
if pocBin != wasPocBin {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d")
}
wasPocBin := pocBin

// ─── 2D: same information when 3D is off ───────────────────────────────────
plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocStrength * close, "POC Share x Price", "#b48cff", 1, "separate")
plot(vaWidth, "Value Width", "#4488ff", 1, "separate")

// ─── 3D: value as terrain, POC as labelled rail, VAH/VAL as edge rails ────
plot3d(pocPrice, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
plot3d(valPrice, "VAL Rail", "line3d", "#ff4477", "3d", 2)

if not insideVA { bgcolor("rgba(255,136,0,0.05)") }

// FIX 1: var lvl = highest(high, 20) froze the level at bar 0 -> plain assignment recomputed every bar.
// FIX 2: close[-1] indexed a future bar -> use close for the current-bar breakout test.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine signature -> OakScript positional (bar_index, price, title, style, color).
// FIX 4: plot3d(r, ..., "3d") forced an oscillator into the price scene -> pane "separate" per PANE LAW.
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")
